import re
chapters=[('海岸','W：水切り','坂・高低差・屋根下・開放面'),('運河遺跡','B：開閉橋','橋上・橋下・石門・段丘・二橋'),('雲上庭園','C：減速雲','屋根・谷底・高台・敵奥への反射'),('結晶峡谷と鉄道遺構','K：反射板','窓・梁・低い反射・上下経路'),('砂漠機関区','U：上昇気流','高台・天井・坑道・盆地'),('極地施設','F：送風域','氷壁・射撃窓・運河・隔壁'),('火山工場','V：噴気孔','炉・天井・橋・火口・排熱口'),('磁力採掘場','M：磁場','段丘・坑道・分断足場・切替端子'),('天空遺跡','既出2種の再構成','雲橋・水の階段・上下島・屋根'),('最終要塞','既出2種の総合','水際・回廊・斜め橋・反射路')]
intro=(out/'rules.md').read_text()
intro=intro.replace('上向き加速度を重力の0.8倍','上向き加速度を重力の1.15倍').replace('上向き加速度=重力の1.2倍','上向き加速度=重力の1.6倍')
intro=intro.replace('頂点に達した際に3発、角度差±12度。1世代のみ','頂点に達した際に3発、角度差±12度。1世代のみ、各子弾のダメージ予算は元の1/3')
parts=[intro]
overview=['| 範囲 | テーマ | 中心ギミック | 構造の変化 |','|---|---|---|---|']
for i,(name,gimmick,variation) in enumerate(chapters):overview.append(f'| {i*10+1}〜{i*10+10} | {name} | {gimmick} | {variation} |')
parts.append('\n'.join(overview))
parts.append('\n### 100面の索引\n')
for i,c in enumerate(chapters):
 parts.append(f'**{c[0]}**：'+ ' ／ '.join(f"{r['level']}. {r['name'].split('／')[1]}" for r in rows[i*10:i*10+10])+'\n')
for i,(theme,_,_) in enumerate(chapters):
 parts.append(f'### エリア{i+1}：{theme} — Lv.{i*10+1}〜{i*10+10}\n')
 for r in rows[i*10:i*10+10]:
  n=int(r['level']);r['theme']=theme;r['kind']='boss' if n%10==0 else 'normal'
  r['target_time']='4〜6分' if n==100 else '3〜5分' if n%10==0 else '1〜2分' if n<=2 or n%10==5 else '2〜4分'
  parts.append(f"#### Lv.{n:03d}｜{r['name']}\n\n**{'ボス戦' if r['kind']=='boss' else '通常戦'}／目標時間：{r['target_time']}**\n\n| 項目 | 個別設計 |\n|---|---|\n"+'\n'.join(f'| {label} | {r[key]} |' for key,label in [('geometry','地形・初期位置'),('gimmick','ギミック・周期'),('skills','支給スキル'),('pickup','浮遊アイテム'),('enemy','敵の行動'),('main','主な攻略と成功体験'),('alternate','別の攻略'),('check','重点検証')])+'\n')
parts.append((out/'bosses.md').read_text())
# Validate authored catalogue, not physical reachability.
first={'BURST':4,'BLINK':12,'PUSH':17,'BOUNCE':24,'PULL':27,'SPLIT':33,'PHASE':52,'SWAP':73}
weapons={};skins=[];bosses=[];counts={}
for r in rows:
 n=int(r['level'])
 skills=re.findall(r'([A-Z]+)×(\d+)',r['skills'])
 assert len(skills)<=2,(n,'too many skills')
 for name,count in skills:
  assert name in first and n>=first[name],(n,name,'before introduction')
  assert 1<=int(count)<=3
 for w in re.findall(r'\bW(\d{2})',r['pickup']):
  assert w not in weapons,(n,'duplicate weapon',w)
  weapons[w]=n
 skins+=re.findall(r'\bS(\d{2})',r['pickup'])
 if n%10==0:bosses.append(n);assert re.match(r'B\d{2}',r['enemy'])
 else:assert re.match(r'E[0-5]',r['enemy'])
 gs=set(re.findall(r'\b[WBCKUFVM](?=[：＋])',r['gimmick']))
 if n!=100:assert len(gs)<=2,(n,gs)
 for g in gs:counts[g]=counts.get(g,0)+1
expected=[3,8,14,19,23,28,34,39,44,49,54,59,64,69,74,79,84,89,94]
assert [weapons[f'{i:02}'] for i in range(2,21)]==expected
assert sorted(skins)==[f'{i:02}' for i in range(1,28)]
assert bosses==list(range(10,101,10))
assert all(r['main']!=r['alternate'] for r in rows)
assert len({r['geometry'] for r in rows})==100
text='\n\n'.join(parts)
assert len(re.findall(r'^#### Lv\.\d{3}',text,re.M))==100
result={'status':'PASS','checks':{'numbered_levels':100,'normal_levels':90,'boss_levels':bosses,'distinct_authored_layout_descriptions':100,'alternative_routes':100,'special_weapon_first_placements':weapons,'normal_cosmetics':len(skins),'skills_no_early_use':True,'skill_slots_maximum':2,'gimmicks_at_most_two_except_staged_final_boss':True},'not_tested':['trajectory reachability','playability','touch UX','balance','performance'],'gimmick_occurrences':counts}
text+='\n\n## 13. 今回の設計整合性チェック結果\n\nレベル1〜100の欠番・重複なし。通常90面、10の倍数のボス10面。全100面に別の攻略経路を記載。特殊武器W02〜W20の初配置は各1回、通常外観S01〜S27は各1回。支給スキルの初登場順と最大2枠を検査。最終ボスを除く同時ギミックは最大2種、最終ボスも各段階で最大2種。これらは文書データのチェック結果であり、実プレイや弾道検証の合格を意味しない。\n'
(out/'ARCLINE_Level_001-100_Design.md').write_text(text)
(out/'level_design_data.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
(out/'design_validation.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
print(json.dumps({'levels':len(rows),'bosses':len(bosses),'weapons':len(weapons)+1,'skins':len(skins)+10,'characters':len(text),'file':str(out/'ARCLINE_Level_001-100_Design.md'),'validation':result['status']},ensure_ascii=False))
